"""
make_trees_doc.py - regenerates Docs/Kits/nature_trees.md from the exported JSON sidecars + validation report.
Run with plain python (outside Blender):  python Tools/blender/nature/make_trees_doc.py
"""
import json, os, glob

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..'))
EXP = os.path.join(ROOT, 'Exports', 'Nature', 'Trees')
OUT = os.path.join(ROOT, 'Docs', 'Kits', 'nature_trees.md')

ORDER = ['pine', 'oak', 'birch', 'palm', 'dead', 'poplar', 'olive']
FAM_TITLE = {
    'pine': 'Conifers - spruce / fir / Scots pine (alpine + forest)',
    'oak': 'Oaks - broadleaf, wide crowns',
    'birch': 'Birches',
    'palm': 'Palms (coastal)',
    'dead': 'Dead / dry scrub trees (desert)',
    'poplar': 'Poplar / cypress - columnar (farmland lines)',
    'olive': 'Olive / young orchard trees (farms)',
}
SPACING = {  # recommended minimum centre spacing / placement notes
    'pine': '4-6 m in forest (crowns overlap by design), 8+ m for hero/roadside',
    'oak': '9-14 m (spreading crowns), solitary or hedgerow; keep >=6 m from the road centre line',
    'birch': '3-5 m groves, multi-stem variant works as a single accent',
    'palm': '5-8 m along coast roads / promenades',
    'dead': '8-20 m, sparse accents on desert terrain and rocky slopes',
    'poplar': '4-6 m in avenue lines (field edges, canals), 3-4 m for a dense windbreak',
    'olive': '5-7 m on a regular grid (orchard) or random in Mediterranean fields',
}

js = {}
for p in sorted(glob.glob(os.path.join(EXP, 'tree_*.json'))):
    d = json.load(open(p, encoding='utf8'))
    js[d['id']] = d
rep = {}
rp = os.path.join(EXP, 'validation_report.json')
if os.path.exists(rp):
    rep = json.load(open(rp, encoding='utf8'))

def fam(aid):
    return aid.split('_')[1]

ids = sorted(js, key=lambda a: (ORDER.index(fam(a)), a))
L = []
w = L.append
w('# Nature kit - TREES (21 assets + 21 far cards)')
w('')
w('Generated by `Tools/blender/nature/make_trees_doc.py` from the exported sidecars (`Exports/Nature/Trees/*.json`). Source of truth for geometry: ')
w('`Tools/blender/nature/trees.py` (asset table + harness) + `treelib.py` (geometry core) + `tree_fams.py` (family builders). Every asset is generated procedurally and idempotently from a seed.')
w('')
w('## 1. Conventions')
w('* Units: 1 Blender unit = 1 m. Z up. **Origin = trunk base centre on the ground (z = 0).** Roots / trunk base are buried 0.3-0.5 m below z = 0 so the tree sits on uneven terrain. Transforms are applied (scale 1, rotation 0, verified).')
w('* One FBX per asset: `Exports/Nature/Trees/<id>.fbx` = tree mesh `<id>` + trunk collision hulls `UCX_<id>_NN`; plus `<id>_Far.fbx` (distance card) and `<id>.json` sidecar. FBX written with the project recipe (`Tools/blender/lib/fbx_export.py`, `center_on="self"`, axis -Y/Z, unit scale applied -> UE centimetres), **vertex colours exported LINEAR** (raw masks, no sRGB conversion).')
w('* FBX re-import round-trip verified (origin at 0,0,0, correct size, `Col` + `UVMap` + material names preserved).')
w('* All opaque geometry (Nanite friendly). No alpha cards inside the tree mesh; leaf / needle "cards" are real single-sided folded geometry (2-8 tris each), so use **two-sided** materials (or Nanite two-sided foliage) on `M_Tree_Leaf*`, `M_Tree_Needle`, `M_Tree_Palm`.')
w('* Import normals from the FBX (custom "ball" normals on foliage give soft crown shading): Static Mesh import -> *Normal Import Method = Import Normals*, tangents = MikkTSpace.')
w('')
w('## 2. Asset list')
w('')
w('| id | name | W x D x H (m) | tris LOD0 | far tris | UCX hulls | material slots | scale range | biome tags |')
w('|---|---|---|---|---|---|---|---|---|')
for a in ids:
    d = js[a]
    dm = d['dimensions']
    w('| `%s` | %s | %.1f x %.1f x %.1f | %s | %d | %d | %s | %.2f-%.2f | %s |' % (
        a, d['display_name'], dm['x'], dm['y'], dm['height'], format(d['tri_counts']['mesh'], ','), d['tri_counts']['far'], len(d['collision']['ucx_hulls']),
        ', '.join('`%s`' % m for m in d['material_slots']), d['scale_range'][0], d['scale_range'][1], ', '.join(d['biome_tags'])))
w('')
tot = sum(js[a]['tri_counts']['mesh'] for a in ids)
w('Total LOD0 triangles over the 21 assets: %s (min %s / max %s per tree). Hero budget from the contract is 20-60 k; every tree is inside it except the small scrub / orchard / palm trees that are intentionally lighter (2-20 k).' % (
    format(tot, ','), format(min(js[a]['tri_counts']['mesh'] for a in ids), ','), format(max(js[a]['tri_counts']['mesh'] for a in ids), ',')))
w('')
for f in ORDER:
    w('### %s' % FAM_TITLE[f])
    for a in [x for x in ids if fam(x) == f]:
        d = js[a]
        w('* **`%s`** - %s. Height %.1f m, crown/extent %.1f m. %s tris, UCX %s. Placement: %s.' % (
            a, d['display_name'], d['dimensions']['height'], max(d['dimensions']['x'], d['dimensions']['y']), format(d['tri_counts']['mesh'], ','),
            ', '.join(d['collision']['ucx_hulls']), SPACING[f]))
    w('')
w('Height targets from the brief: pine 12-22 m, oak 10-16 m, birch 8-14 m, palm 6-12 m, scrub 3-5 m, poplar 15-25 m, olive 4-6 m - all assets are inside these ranges at scale 1.0 (apply the listed UE scale range for variety).')
w('')
w('## 3. Materials (Blender material name == UE material-instance name)')
w('| slot | used by | look | notes |')
w('|---|---|---|---|')
w('| `M_Tree_Bark` | oak, pine, palm, olive, poplar trunks; birch twigs | dark grey-brown fissured bark | tiling UVs: U wraps once per ring, V = 0.25-0.5 per metre of length. Blender preview adds procedural vertically elongated Voronoi cracks + bump |')
w('| `M_Tree_Bark_Birch` | birch trunks + limbs | white paper bark | smooth; the black marks are **real geometry**, see below |')
w('| `M_Tree_Bark_Dark` | birch only | near-black fissured bark | (a) the trunk foot (< ~0.3-0.45 m, deep ridged relief), (b) pointed bark "tongues" rising up to ~1 m (`bark_tongues`, 4-8 tris each, 7 mm above the trunk), (c) lens-shaped horizontal lenticels (`lenticel_marks`, 6-26 cm x 1-2 cm, 8 tris each) on trunk and limbs. No face colouring, so nothing is quantised to the face grid |')
w('| `M_Tree_Leaf` | oak, poplar_a | mid-dark green broadleaf | two-sided; leaf cards UV 0-1 per card (a leaf texture with alpha-clip can be put on the cards for close-up detail). Specular 0 (no pale sheen on the leaf masses) |')
w('| `M_Tree_LeafLight` | birch, poplar_c | light yellow-green broadleaf | |')
w('| `M_Tree_LeafDry` | olive_a/b/c, dead_b, dead_c, palm_b (dead-frond skirt) | grey-olive / straw dry foliage | |')
w('| `M_Tree_Needle` | spruce/fir/Scots pine, cypress | dark blue-green needles | feather sprays on needle-sleeved twigs + dark "skirt" tiers; the outer part of each twig is a green sleeve (needle material) so no bare brown rachis shows |')
w('| `M_Tree_Palm` | all palms (fronds, rachis, nuts) | bright palm green | |')
w('| `M_Tree_Dead` | dead_a/b/c | weathered grey-tan wood | peeled patches + deep fissures + clefts are geometry; Blender preview adds Voronoi cracks |')
w('| `M_Tree_Far_<id>` | `<id>_Far` only | baked colour+alpha card | texture `Exports/Nature/Trees/Textures/T_<id>_Far.png` (power-of-two), alpha clip ~0.33, two-sided |')
w('')
w('The contract lists 5 tree materials (`M_Tree_Bark`, `M_Tree_Leaf`, `M_Tree_Needle`, `M_Tree_Palm`, `M_Tree_Dead`); `M_Tree_Bark_Birch`, `M_Tree_Bark_Dark`, `M_Tree_LeafLight`, `M_Tree_LeafDry` were added because white birch bark with black marks and the lighter / grey foliage cannot be expressed by one shared instance. Max 4 slots per asset (birch), 1-3 for the rest. Leaf / needle / palm materials have specular 0 and the leaf-mass cores are darkened through the baked AO channel (B) so no pale sheen shows through gaps.')
w('')
w('## 4. Vertex colours = wind (attribute `Col`, exported LINEAR)')
w('* **R = branch flex** 0 at the trunk base -> ~0.2 at the fork -> 1 at twig / leaf tips (hierarchical: a branch inherits the value where it leaves its parent).')
w('* **G = leaf flutter** 0 on wood -> ~0.3 at the base of a leaf card -> 1 at the free tip; leaf-mass cores ~0.1.')
w('* **B = baked ambient occlusion** (real ray-cast AO inside the tree, 1 = open sky, floor 0.16; one sample per leaf card). Multiply base colour by `lerp(0.35, 1, B)` and/or feed Lumen-free ambient.')
w('* UE material hint: `WPO = windDir * (R^2 * lowFreqSway + G * highFreqNoise)`; trunk base (R=0) never moves.')
w('')
w('## 5. Collision')
w('* `UCX_<id>_NN`: convex hulls (<= 32 verts, verified convex + closed) around the **trunk only** (capsule-like, lower 3-7 m of the trunk, flared at the base). **One hull per stem**: `tree_birch_b` has 3 hulls (3 stems), `tree_olive_c` 2 hulls (split trunk); palms get 2 stacked hulls following the curved trunk. **Canopy / foliage has no collision.** The validation report records `ucx_cover_pct` = share of bark vertices at 0.35-1.0 m height that lie inside a hull box (+12 cm); every tree is >= 94 %, multi-stem trees 100 %.')
w('* UE: import with *Auto Generate Collision = off* (the UCX hulls are used), Collision Complexity = **Use Simple As Complex**, preset BlockAll (or a custom `Foliage` profile: block Vehicle + Pawn, ignore Camera). Mass / physics: static, never simulate.')
w('* Hull radius is ~0.88-0.95 of the real trunk radius at that height so a vehicle clipping bark does not feel an invisible wall.')
w('')
w('## 6. Far cards (`<id>_Far`)')
w('* Two crossed vertical quads (4 tris, UV 0-1) centred on the trunk, width = crown diameter, height = tree height, origin at the base centre. Texture = software-rasterised silhouette + colour of the actual tree from two orthogonal views, atlas `[view along +Y | view along -X]` (left half on the X-Z quad, right half on the Y-Z quad), RGBA with alpha. **Every atlas is power-of-two** (each half-view canvas is a POT rectangle that maps exactly onto its quad, so texels are slightly non-square), edge colours are bled into transparent texels so mips / alpha clip show no dark halo. Sizes (px): ' + ', '.join('%s %dx%d' % (a.replace('tree_', ''), js[a]['far_card']['texture_px'][0], js[a]['far_card']['texture_px'][1]) for a in ids) + '.')
w('* Intended use: HLOD / distance impostor beyond ~120-200 m (smaller trees: 80-120 m), alpha-masked (clip ~0.33), two-sided. Nanite handles LOD0 up to there, so the cards are optional.')
w('')
w('## 7. Recommended UE import / usage')
w('* Static Mesh: **Build Nanite = on** for LOD0 meshes (all opaque), off for `_Far`; Generate Lightmap UVs = off; Vertex Color Import = *Replace*; Combine Meshes = off (the FBX contains the mesh + its UCX hulls, UE pairs them by name).')
w('* Use Instanced Foliage / PCG with the scale range from the table, random yaw, small random pitch (<= 3 deg), `Align to Normal` off for trunks (trees grow vertical), sink 0-10 cm.')
w('* Do not scale non-uniformly; scaling 0.75-1.3 uniformly keeps hull / collision correct.')
w('* Material tip: drive hue shift per instance (PerInstanceRandom) on `M_Tree_Leaf*` for variation, fade `B` (AO) in with distance.')
w('')
w('## 8. Regenerating')
w('Inside the shared Blender (MCP :9889):')
w('```python')
w("NS = {'TREE_IDS': ['tree_oak_a'], 'TREE_AO': True, 'TREE_FAR': True, 'TREE_EXPORT': True}")
w('P = r"<project>/Tools/blender/nature/trees.py"')
w("exec(compile(open(P, encoding='utf8').read(), P, 'exec'), NS)")
w('```')
w('Staging in Blender: trees at `x = 400 + 34*index, y = 60` (family order pine, oak, birch, palm, dead, poplar, olive; a/b/c), far cards at `y = 180`, collection `FORZA_UE/Nature/Trees`. Then `python Tools/blender/nature/make_trees_doc.py` refreshes this document.')
w('')
w('## 9. Validation summary (automated, `Exports/Nature/Trees/validation_report.json`)')
w('| id | tris | verts | scale applied | ground ok | UV ok | col range R/G/B | closed pieces (inverted) | open card pieces | non-manifold edges | UCX verts (convex) | trunk covered by UCX |')
w('|---|---|---|---|---|---|---|---|---|---|---|---|')
for a in ids:
    r = rep.get(a)
    if not r: continue
    uc = ', '.join('%d%s' % (v['verts'], '' if v['convex'] else '!') for v in r['ucx'].values())
    w('| `%s` | %s | %s | %s | %s | %s | %s | %d (%d) | %d | %d | %s | %s |' % (
        a, format(r['tris'], ','), format(r['verts'], ','), 'yes' if r['scale_ok'] else 'NO', 'yes' if r['ground_ok'] else 'NO', 'yes' if r['uv_finite'] else 'NO',
        '/'.join('%.1f-%.1f' % tuple(c) for c in r['col_range']), r['closed_pieces'], r['inverted_closed_pieces'], r['open_pieces'], r['nonmanifold_edges'], uc,
        ('%.1f %%' % r['ucx_cover_pct']) if 'ucx_cover_pct' in r else 'n/a'))
w('')
w('Checks run on every asset: object names (`<id>`, `UCX_<id>_NN`, `<id>_Far`), pivot / ground (lowest point between -0.6 m and 0), applied transforms, closed pieces have outward normals (signed volume > 0), no >2-face edges, `UVMap` finite, colour attribute present, material slot names, triangle budget, hulls convex and <= 32 verts. Open edges exist only on the single-sided leaf / needle cards by design.')
w('')
w('## 10. Revision 2 - what changed after the art-director review')
w('* **Birch (a/b/c):** the quantised square dark patches are gone. Lenticels are thin lens-shaped geometry strips lying on the real trunk surface; the foot is black ridged bark with pointed tongues rising from it (geometry, not face colouring); fork collars added; floating fill clumps pulled back to the branches; `tree_birch_c` is now a leaning, low-forking weeping birch (clearly different from `tree_birch_a`).')
w('* **Collision:** `UCX_tree_birch_b_01..03` (one per stem) and `UCX_tree_olive_c_01..02` (both trunks). The engine now emits one hull per stem for every tree; coverage is verified numerically (`ucx_cover_pct`).')
w('* **Palms:** real trunk relief (sawtooth ring scars, fibre ridges, diamond leaf-base pattern on the fan palm, much stronger basal swelling), exposed root mass, retained leaf-base boots, curved drooping leaflets, forked-tip fan fronds, straw-coloured dead-frond skirt (fan palm), proper coconut ellipsoids with stalks.')
w('* **Dead / scrub trees:** `tree_dead_a` has deep fissures, peeled patches, three real vertical clefts, 3 thick limbs that thin gradually and snapped splinters (no flat sawn-off top); `tree_dead_c` now uses sparse dry foliage with bare dead twigs (no lush green); `tree_dead_b` lost its boxy stub and got a centre canopy mass; all leaf cores darkened / hidden.')
w('* **Conifers:** shorter, denser needle strips on needle-sleeved twigs (no bare brown rachis, fewer fern-like fronds); `tree_pine_b` is now a whorled subalpine fir spire (clearly different from the dense spruce `a`); `tree_pine_c` has hanging lower arms, dead-branch stubs and needle-tuft pads instead of leaf-like cards.')
w('* **Oaks:** branch collars (limbs flare into the trunk), deeper fissured relief, roots grow out of the trunk flare lobes (no more sausage fins), crown centre of `tree_oak_c` filled.')
w('* **Poplars / cypress:** continuous flame crowns (axis fill between the side-branch tiers, pointed leaders), `tree_poplar_b` trimmed to 39 k tris, `tree_poplar_c` slimmed to 5.8 m width.')
w('* **Olives:** more twist / hollows in `a`, thicker trunk + short roots + narrow leaves in `b`, centre clumps (no donut) and per-trunk collision in `c`.')
w('* **Materials:** bark colour darkened and desaturated (grey-brown), `M_Tree_Dead` weathered grey-tan, new `M_Tree_Bark_Dark`, specular 0 on all foliage, preview cracks (voronoi) on bark; leaf-mass cores darkened by AO so the pale blue-grey sheen is gone.')
w('* **Far cards:** all 21 atlases are power-of-two with bled edges (previously NPOT like 322x303).')
w('')
w('## 10b. Revision 3 - fixes after the second art-director review (round 2: `tree_pine_b` and `tree_pine_c` failed)')
w('* **`tree_pine_b` (subalpine fir):** the smooth hard-rimmed "lampshade" tier skirts are gone as a read: the skirt is now a small ragged cone (per-sector radius jitter, alternating drooping teeth / notches, `skirt_rough`) hidden behind the sprays. Every whorl branch carries 2 side twigs (fuller, 3-D sprays instead of a flat feather), short branchlets sit between the whorls (hide the bare trunk), whorl spacing / radius are irregular (+-30 % spacing, hash-driven per-whorl size), 8 % of the branches are missing and 10 % are broken / stunted, the spire leans slightly. Needle strips are wider (0.105 m) for needle-mass volume. 56 k tris (was 25 k).')
w('* **`tree_pine_c` (Scots pine) rebuilt with a dedicated builder (`build_scots`):** no more dome-on-a-stick and no rope bundle. Slender curved trunk with root flare and dead-branch stubs; the crown starts at ~2.5 m with three long **drooping lower limbs** (hanging pads) and continues with 9 thick **limbs forking at distinct heights** (4.4-11.8 m, golden-angle azimuths, collar at the trunk, diverging outward, shorter and more upturned towards the top, longer on the lee side = wind-swept). Each limb ends in an irregular **plate** of flattened needle-tuft pads (terminal pad + 5 pads along the outer half + side twigs with their own pads); 5 short side branches carry small pads down the upper trunk, 6 pads sit inside the crown near the stem, a few cap the leader. Needle cards are shorter / fatter (0.38 x 0.07 m diamonds, underside culled) on a dark core mass. 39 k tris, 15.2 m x 9.1 m.')
w('* **`tree_pine_a`:** ragged skirt rim (no smooth lampshade edge) and per-spray droop variation (hash).')
w('* **`tree_oak_b`:** limbs now have clearly different thickness (per-limb radius list) and fork heights (stagger 1.6 m) and splay wider: no more "broom" of equal poles. **`tree_oak_c`:** 6 extra clumps round the crown top and fill the gaps seen from above.')
w('* **Birch:** lenticel bands are wider / longer (up to 0.42 m x 3 cm) so the black marking survives at 30-50 m; limb / fork tubes use more sides (10 / 7 / 5) for smoother collars. (`tree_birch_b` lower side branches were tried and rejected: they formed a visible leaf ring.)')
w('* **Palms:** `tree_palm_a` has stronger frond length / droop variation; `tree_palm_c` has 9 more upright young central fronds (fuller crown).')
w('* **Dead / scrub:** `tree_dead_a` has 4/4/3 sub-branches per level (many more thin dead twigs on the three forks, 8 k tris); `tree_dead_c` exposes more bare twigs through the crown.')
w('* **Poplars:** `tree_poplar_a` leans and has a lumpier crown above a longer bare trunk (tris 48 k -> 39 k); `tree_poplar_b` (cypress) leans slightly and tapers to a pointed asymmetric tip; the detached top clump of poplar_b / poplar_c is merged into the crown (axis fill extended to the leader, lateral hash jitter breaks the stacked-lump banding of poplar_c).')
w('* **Olives:** `tree_olive_b` uses the grey-green `M_Tree_LeafDry` (reads as olive / orchard tree, no more bright generic deciduous green); `tree_olive_c` is uniformly fitted to 5.92 m (was 6.06 m; brief 4-6 m) by the new `max_h` asset option, hulls scaled with it.')
w('* **Preview materials:** the Voronoi bark crack pattern is stretched vertically (long fissures instead of a hex pattern); preview only, no effect on the FBX.')
w('* **Non-Nanite platforms:** every `_Far` card is the LOD fallback; for mid-range LODs without Nanite, decimate the foliage cards (the vertex-colour masks survive) or bake an impostor atlas from the same script. All 21 meshes are opaque geometry (Nanite) by design.')
w('')
w('## 11. Known weaknesses (honest list)')
w('* **Foliage is geometric, not textured:** leaves / needles are flat-shaded folded cards (2-8 tris) with soft ball normals. Reads well from the road and mid distance, a little stylised / low-poly in extreme close-ups. A masked leaf texture on the 0-1 card UVs in `M_Tree_Leaf*` would add the missing micro detail.')
w('* Conifer branch sprays are "fishbone" cards on needle-sleeved twigs + a small ragged skirt per tier: believable layered silhouette, but needles are not individually modelled; the skirts are still smooth cones seen from directly above. `tree_pine_c` uses flattened radial needle-tuft pads that read as Scots-pine foliage plates from 5+ m but look a little tidy / stylised (cloud-pruned) and spiky in close-ups. `tree_pine_b` is airy: the trunk stays visible between whorls at close range.')
w('* Crown interiors: inner branches are only visible from below / through gaps (clumps cull their inward-facing cards). Branch structure is complete under the canopy but not meant for inside-the-crown cameras.')
w('* Wind masks are hierarchical (branch -> tip), **not** per-leaf-cluster pivot data; very large clumps sway as one unit in the vertex shader. No Pivot-Painter / per-clump pivot is baked.')
w('* AO (B) is one ray-cast sample per leaf card and per vertex on wood; no ground-bounce / sky colour is baked.')
w('* Bark relief is real geometry (fissures, clefts, peels, root buttresses, birch lenticels / tongues) but no normal map or albedo texture is shipped: the UE side supplies bark / leaf textures. Blender previews use procedural node materials only (voronoi cracks are preview-only).')
w('* Palm leaflets are 6-8 tri curved strips and the fan-palm fronds are forked-tip fans, not individually split fronds; coconut clusters are 9 smooth ellipsoids hidden mostly under the fronds.')
w('* Birch lenticels / tongues are modelled geometry (about 1-3 k tris per trunk); at very long distance they are sub-pixel and the far card carries them as speckle only.')
w('* Only 3 variants per family (distinct silhouettes, not a continuous parameter space). More seeds can be generated from the same script by adding rows to `ASSETS`. `tree_birch_b` (multi-stem) still shows a gap between the lower and upper clump groups from some angles (bouquet read).')
w('* Several trees are heavy (pine_b 56 k, pine_a 48 k, poplar_c 46 k, oak_c 45 k, birch_b 44 k tris): intended for Nanite; for non-Nanite platforms use the `_Far` card or add LODs.')
w('* Collision is trunk-only convex hulls (very low-poly capsules); thick root flares beyond the hull radius are not collidable.')
w('* Far-card textures are flat-lit colour bakes (no normal / roughness) from two views; crossed cards show view-dependent popping typical of cross billboards.')
w('')
w('## 12. Files')
w('```')
w('Tools/blender/nature/trees.py        asset table, harness, validation, export')
w('Tools/blender/nature/treelib.py      geometry core (tubes, leaf cards, clumps, AO bake, UCX, far-card raster, materials)')
w('Tools/blender/nature/tree_fams.py    family builders (conifer, crown-tree engine, palms)')
w('Tools/blender/nature/make_trees_doc.py   regenerates this document')
w('Exports/Nature/Trees/<id>.fbx, <id>_Far.fbx, <id>.json, validation_report.json')
w('Exports/Nature/Trees/Textures/T_<id>_Far.png')
w('```')
w('')
os.makedirs(os.path.dirname(OUT), exist_ok=True)
open(OUT, 'w', encoding='utf8').write('\n'.join(L))
print('wrote', OUT, len(L), 'lines')
